diff --git a/packages/fa_llm_mock/lib/src/mock_llm_server.dart b/packages/fa_llm_mock/lib/src/mock_llm_server.dart
index 5d3f08b10..518fdc514 100644
--- a/packages/fa_llm_mock/lib/src/mock_llm_server.dart
+++ b/packages/fa_llm_mock/lib/src/mock_llm_server.dart
@@ -68,6 +68,13 @@ final class MockLlmServer {
   var _chatCalls = 0;
   final _chatBodies = <String>[];

+  var _abortedRequests = 0;
+
+  /// Connections the CLIENT hung up on mid-request or mid-response (the
+  /// crash-test norm: a PTY test SIGKILLs the CLI while a turn is in
+  /// flight). Diagnostics only — served behavior is unchanged.
+  int get abortedRequests => _abortedRequests;
+
   /// The base URL to pass as the CLI's `--base-url` (trailing `/v1`, so the
   /// adapter's `{baseUrl}/chat/completions` lands on `/v1/chat/completions`).
   final String baseUrl;
@@ -87,7 +94,7 @@ final class MockLlmServer {
             'http://127.0.0.1:${server.port}/v1',
             script,
           );
-    server.listen(mock._handle);
+    server.listen((HttpRequest request) => unawaited(mock._serve(request)));
     return mock;
   }

@@ -119,6 +126,35 @@ final class MockLlmServer {
   /// Closes the server and every open connection.
   Future<void> stop() => _server.close(force: true);

+  /// Serves one request, tolerating CLIENT-side connection aborts (issue
+  /// #1385). A PTY test's `hardKill` (SIGKILL of the CLI) lands wherever
+  /// the scheduler decides — including mid-request-send, so the server's
+  /// parser sees a half-delivered body and `_HttpIncoming.listen` rethrows
+  /// the parser's `HttpException("Connection closed while receiving data")`
+  /// carrying the request-line path (`uri = /v1/chat/completions` — the
+  /// exact 2026-10-07 shard-red signature). Unguarded, that error escaped
+  /// `_handle` into `HttpServer.listen`'s handler-error sink — an UNHANDLED
+  /// ZONE ERROR in the test isolate, which dart test attributes to whichever
+  /// test is active. Tolerated here instead: the client is gone, nothing can
+  /// consume a response, and the scripted queue stays aligned (the aborted
+  /// request never reached `_nextEntry`, so no response is popped).
+  ///
+  /// Deliberately CLASS-based (HttpException / SocketException — dart:io's
+  /// dead-peer shapes for the read and write legs) rather than
+  /// message-matching: SDK versions word these differently, and a mock must
+  /// never turn a client death into a red test. Any other error still
+  /// propagates loudly (script misuse surfaces as 500 responses, never as
+  /// handler exceptions).
+  Future<void> _serve(HttpRequest request) async {
+    try {
+      await _handle(request);
+    } on HttpException {
+      _abortedRequests++;
+    } on SocketException {
+      _abortedRequests++;
+    }
+  }
+
   Future<void> _handle(HttpRequest request) async {
     final path = request.uri.path;
     if (request.method == 'POST' && path.endsWith('/chat/completions')) {
diff --git a/packages/fa_llm_mock/test/mock_llm_server_test.dart b/packages/fa_llm_mock/test/mock_llm_server_test.dart
index 220bef3e1..aafb23a62 100644
--- a/packages/fa_llm_mock/test/mock_llm_server_test.dart
+++ b/packages/fa_llm_mock/test/mock_llm_server_test.dart
@@ -356,4 +356,93 @@ responses:
     final response = await request.close();
     expect(response.statusCode, 404);
   });
+
+  test(
+    'client abort mid-request leaks no unhandled error, queue stays aligned '
+    '(issue #1385)',
+    () async {
+      server.enqueueText('after the abort');
+      // A client that dies mid-request the way a SIGKILLed CLI does
+      // (steering PTY test phase 2: hardKill races the soft-yield turn's
+      // request): headers declare a 64-byte body, 5 bytes arrive, then a
+      // clean FIN. TCP orders data before EOF, so the server parser is
+      // deterministically mid-body when the socket closes — the exact
+      // shape that used to rethrow
+      // `HttpException("Connection closed while receiving data",
+      // uri: /v1/chat/completions)` out of the handler and into the test
+      // zone as an unhandled error (the 2026-10-07 shard reds).
+      final socket = await Socket.connect('127.0.0.1', server.port);
+      socket.add(
+        utf8.encode(
+          'POST /v1/chat/completions HTTP/1.1\r\n'
+          'Host: 127.0.0.1:${server.port}\r\n'
+          'Content-Type: application/json\r\n'
+          'Content-Length: 64\r\n'
+          '\r\n'
+          '{"a":',
+        ),
+      );
+      await socket.flush();
+      await socket.close();
+      // The abort surfaces asynchronously on the server side — pump the
+      // event loop so a leaked (unhandled) error would land inside THIS
+      // test: dart test fails the active test on any unhandled zone error,
+      // which is precisely the leak this guard pins.
+      await Future<void>.delayed(const Duration(milliseconds: 100));
+      expect(server.abortedRequests, 1);
+      socket.destroy();
+      // The next, well-formed client is served the scripted response — the
+      // aborted request consumed nothing from the queue.
+      final (status, body) = await postChat([
+        {'role': 'user', 'content': 'still here'},
+      ]);
+      expect(status, 200);
+      expect(
+        _sseChunks(body).first['choices'].first['delta']['content'],
+        'after the abort',
+      );
+    },
+  );
+
+  test(
+    'client abort mid-response leaks no unhandled error (issue #1385)',
+    () async {
+      server.enqueueText('doomed');
+      server.enqueueText('next');
+      // A full request whose client is gone by the time the response is
+      // written — the other hardKill window (kill after dispatch, before
+      // the CLI consumed the SSE bytes). An orderly close keeps the request
+      // delivery deterministic (FIN never discards receive buffers, so the
+      // server always parses the full body and pops the scripted entry)
+      // while the response write races a closing socket — which must stay
+      // a tolerated abort, never an unhandled zone error. Whether the
+      // write itself errors is platform-timing, so only the LEAK and the
+      // queue alignment are pinned here.
+      final socket = await Socket.connect('127.0.0.1', server.port);
+      socket.add(
+        utf8.encode(
+          'POST /v1/chat/completions HTTP/1.1\r\n'
+          'Host: 127.0.0.1:${server.port}\r\n'
+          'Content-Type: application/json\r\n'
+          'Content-Length: ${'{"a":1}'.length}\r\n'
+          '\r\n'
+          '{"a":1}',
+        ),
+      );
+      await socket.flush();
+      await socket.close();
+      await Future<void>.delayed(const Duration(milliseconds: 100));
+      socket.destroy();
+      // The full request dispatched, so its scripted response is spent;
+      // the next client gets the following scripted entry.
+      final (status, body) = await postChat([
+        {'role': 'user', 'content': 'still here'},
+      ]);
+      expect(status, 200);
+      expect(
+        _sseChunks(body).first['choices'].first['delta']['content'],
+        'next',
+      );
+    },
+  );
 }
