    await postChat([
      {'role': 'user', 'content': 'run'},
      {'role': 'tool', 'content': 'marker-from-tool'},
    ]);
    final (_, body) = await postChat([
      {'role': 'user', 'content': 'run'},
      {'role': 'tool', 'content': 'marker-from-tool'},
    ]);
    final chunks = _sseChunks(body);

    expect(
      chunks.first['choices'].first['delta']['content'],
      'marker-from-tool',
